#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
game_result simulate_game(const unsigned char*a,size_t na,const unsigned char*b,size_t nb){size_t total=na+nb,counts[2]={na,nb};unsigned char*hands[2]={(unsigned char*)malloc(total+1),(unsigned char*)malloc(total+1)},*pile=(unsigned char*)malloc(total+1);if(na)memcpy(hands[0],a,na);if(nb)memcpy(hands[1],b,nb);unsigned char**seen=NULL;size_t ns=0,np=0;int turn=0,debt=0;game_result result={false,0,0};for(;;){if(!np){unsigned char*state=(unsigned char*)malloc(total+1+sizeof(size_t));state[0]=(unsigned char)turn;memcpy(state+1,&counts[0],sizeof(size_t));memcpy(state+1+sizeof(size_t),hands[0],counts[0]);memcpy(state+1+sizeof(size_t)+counts[0],hands[1],counts[1]);bool repeat=false;for(size_t i=0;i<ns;i++)if(!memcmp(seen[i],state,total+1+sizeof(size_t))){repeat=true;break;}if(repeat){free(state);result.loop=true;break;}seen=(unsigned char**)realloc(seen,(ns+1)*sizeof(unsigned char*));seen[ns++]=state;}if(!counts[turn]){result.tricks+=np?1:0;break;}unsigned char c=hands[turn][0];memmove(hands[turn],hands[turn]+1,--counts[turn]);pile[np++]=c;result.cards++;if(c){debt=c;turn=1-turn;}else if(debt){if(!--debt){int winner=1-turn;memcpy(hands[winner]+counts[winner],pile,np);counts[winner]+=np;np=0;result.tricks++;if(!counts[0]||!counts[1])break;turn=winner;}}else turn=1-turn;}for(size_t i=0;i<ns;i++)free(seen[i]);free(seen);free(hands[0]);free(hands[1]);free(pile);return result;}

